public enum Edit: Hashable, Equatable, Sendable {
    case addTrack(kind: TrackKind, magnetic: Bool)
    case insertMedia(track: String, source: String, startUs: Int64, sourceInUs: Int64, durationUs: Int64)
    case insertText(track: String, startUs: Int64, durationUs: Int64, text: String)
    case move(clip: String, track: String, startUs: Int64)
    case trimStart(clip: String, startUs: Int64)
    case trimEnd(clip: String, endUs: Int64)
    case split(clip: String, atUs: Int64)
    case delete(clip: String, ripple: Bool)
    case setSpeed(clip: String, speed: Double)
    /// A copy right after the clip (a full layer gets a new track above).
    case duplicate(clip: String)
    /// Onto a new track at `index` (0 = bottom), starting at `start_us`.
    case moveToNewTrack(clip: String, index: UInt32, startUs: Int64)
    case removeTrack(track: String)
    /// `None` leaves a flag as it is.
    case setTrackFlags(track: String, muted: Bool?, hidden: Bool?, locked: Bool?)
    /// The transition from `clip` into the next clip (a catalogue transition id), or none.
    case setTransition(clip: String, kind: String?, durationUs: Int64)
    /// A clip's In / Out / Loop animation (`animation_presets` id), or none.
    case setAnimation(clip: String, kind: AnimationKind, preset: String?)
    /// A built-in text style (`text_style_presets` id) on text clips.
    case applyStylePreset(clips: [String], preset: String)
    /// Timed captions (e.g. from speech-to-text) as text clips in one caption set; returns the
    /// set's link id. `style_preset`: a `text_style_presets` id.
    case insertCaptions(track: String?, segments: [CaptionSegmentInfo], stylePreset: String?)
