    case unlink(link: String)
    case moveKeyframe(clip: String, path: String, keyframe: String, atUs: Int64)
    case setKeyframeEasing(clip: String, path: String, keyframe: String, easing: EasingKind)
    /// A built-in text animation (`text_animation_presets`) on text clips, replacing theirs
    /// of that kind, or none.
