    @inlinable static func decode(from reader: inout WireReader) -> Edit {
        let tag = reader.readU32()
        switch tag {
        case 0:
            return .addTrack(kind: TrackKind(rawValue: reader.readI32())!, magnetic: reader.readBool())
        case 1:
            return .insertMedia(track: reader.readString(), source: reader.readString(), startUs: reader.readI64(), sourceInUs: reader.readI64(), durationUs: reader.readI64())
        case 2:
            return .insertText(track: reader.readString(), startUs: reader.readI64(), durationUs: reader.readI64(), text: reader.readString())
        case 3:
            return .move(clip: reader.readString(), track: reader.readString(), startUs: reader.readI64())
        case 4:
            return .trimStart(clip: reader.readString(), startUs: reader.readI64())
        case 5:
            return .trimEnd(clip: reader.readString(), endUs: reader.readI64())
        case 6:
            return .split(clip: reader.readString(), atUs: reader.readI64())
        case 7:
            return .delete(clip: reader.readString(), ripple: reader.readBool())
        case 8:
            return .setSpeed(clip: reader.readString(), speed: reader.readF64())
        case 9:
            return .duplicate(clip: reader.readString())
        case 10:
            return .moveToNewTrack(clip: reader.readString(), index: reader.readU32(), startUs: reader.readI64())
        case 11:
            return .removeTrack(track: reader.readString())
        case 12:
            return .setTrackFlags(track: reader.readString(), muted: reader.readOptional { reader in reader.readBool() }, hidden: reader.readOptional { reader in reader.readBool() }, locked: reader.readOptional { reader in reader.readBool() })
        case 13:
            return .setTransition(clip: reader.readString(), kind: reader.readOptional { reader in reader.readString() }, durationUs: reader.readI64())
        case 14:
            return .setAnimation(clip: reader.readString(), kind: AnimationKind(rawValue: reader.readI32())!, preset: reader.readOptional { reader in reader.readString() })
        case 15:
            return .applyStylePreset(clips: reader.readArray { reader in reader.readString() }, preset: reader.readString())
        case 16:
            return .insertCaptions(track: reader.readOptional { reader in reader.readString() }, segments: reader.readArray { reader in CaptionSegmentInfo.decode(from: &reader) }, stylePreset: reader.readOptional { reader in reader.readString() })
        case 17:
            return .link(kind: LinkType(rawValue: reader.readI32())!, clips: reader.readArray { reader in reader.readString() })
        case 18:
            return .unlink(link: reader.readString())
        case 19:
            return .moveKeyframe(clip: reader.readString(), path: reader.readString(), keyframe: reader.readString(), atUs: reader.readI64())
        case 20:
            return .setKeyframeEasing(clip: reader.readString(), path: reader.readString(), keyframe: reader.readString(), easing: EasingKind.decode(from: &reader))
        case 21:
            return .setTextAnimation(clips: reader.readArray { reader in reader.readString() }, kind: TextAnimationKind(rawValue: reader.readI32())!, preset: reader.readOptional { reader in reader.readString() })
