    @inlinable func encode(to writer: inout WireWriter) {
        switch self {
        case let .addTrack(kind, magnetic):
            writer.writeU32(0)
            writer.writeI32(kind.rawValue)
            writer.writeBool(magnetic)
        case let .insertMedia(track, source, startUs, sourceInUs, durationUs):
            writer.writeU32(1)
            writer.writeString(track)
            writer.writeString(source)
            writer.writeI64(startUs)
            writer.writeI64(sourceInUs)
            writer.writeI64(durationUs)
        case let .insertText(track, startUs, durationUs, text):
            writer.writeU32(2)
            writer.writeString(track)
            writer.writeI64(startUs)
            writer.writeI64(durationUs)
            writer.writeString(text)
        case let .move(clip, track, startUs):
            writer.writeU32(3)
            writer.writeString(clip)
            writer.writeString(track)
            writer.writeI64(startUs)
        case let .trimStart(clip, startUs):
            writer.writeU32(4)
            writer.writeString(clip)
            writer.writeI64(startUs)
        case let .trimEnd(clip, endUs):
            writer.writeU32(5)
            writer.writeString(clip)
            writer.writeI64(endUs)
        case let .split(clip, atUs):
            writer.writeU32(6)
            writer.writeString(clip)
            writer.writeI64(atUs)
        case let .delete(clip, ripple):
            writer.writeU32(7)
            writer.writeString(clip)
            writer.writeBool(ripple)
        case let .setSpeed(clip, speed):
            writer.writeU32(8)
            writer.writeString(clip)
            writer.writeF64(speed)
        case let .duplicate(clip):
            writer.writeU32(9)
            writer.writeString(clip)
        case let .moveToNewTrack(clip, index, startUs):
            writer.writeU32(10)
            writer.writeString(clip)
            writer.writeU32(index)
            writer.writeI64(startUs)
        case let .removeTrack(track):
            writer.writeU32(11)
            writer.writeString(track)
        case let .setTrackFlags(track, muted, hidden, locked):
            writer.writeU32(12)
            writer.writeString(track)
            writer.writeOptional(muted) { writer, boltffiValue0 in writer.writeBool(boltffiValue0) }
            writer.writeOptional(hidden) { writer, boltffiValue0 in writer.writeBool(boltffiValue0) }
            writer.writeOptional(locked) { writer, boltffiValue0 in writer.writeBool(boltffiValue0) }
        case let .setTransition(clip, kind, durationUs):
            writer.writeU32(13)
            writer.writeString(clip)
            writer.writeOptional(kind) { writer, boltffiValue0 in writer.writeString(boltffiValue0) }
            writer.writeI64(durationUs)
        case let .setAnimation(clip, kind, preset):
            writer.writeU32(14)
            writer.writeString(clip)
            writer.writeI32(kind.rawValue)
            writer.writeOptional(preset) { writer, boltffiValue0 in writer.writeString(boltffiValue0) }
        case let .applyStylePreset(clips, preset):
            writer.writeU32(15)
            writer.writeArray(clips) { writer, boltffiValue0 in writer.writeString(boltffiValue0) }
            writer.writeString(preset)
        case let .insertCaptions(track, segments, stylePreset):
            writer.writeU32(16)
            writer.writeOptional(track) { writer, boltffiValue0 in writer.writeString(boltffiValue0) }
            writer.writeArray(segments) { writer, boltffiValue0 in boltffiValue0.encode(to: &writer) }
            writer.writeOptional(stylePreset) { writer, boltffiValue0 in writer.writeString(boltffiValue0) }
        case let .link(kind, clips):
            writer.writeU32(17)
            writer.writeI32(kind.rawValue)
            writer.writeArray(clips) { writer, boltffiValue0 in writer.writeString(boltffiValue0) }
        case let .unlink(link):
            writer.writeU32(18)
            writer.writeString(link)
        case let .moveKeyframe(clip, path, keyframe, atUs):
            writer.writeU32(19)
            writer.writeString(clip)
            writer.writeString(path)
            writer.writeString(keyframe)
            writer.writeI64(atUs)
        case let .setKeyframeEasing(clip, path, keyframe, easing):
            writer.writeU32(20)
            writer.writeString(clip)
            writer.writeString(path)
            writer.writeString(keyframe)
            easing.encode(to: &writer)
        case let .setTextAnimation(clips, kind, preset):
            writer.writeU32(21)
            writer.writeArray(clips) { writer, boltffiValue0 in writer.writeString(boltffiValue0) }
            writer.writeI32(kind.rawValue)
            writer.writeOptional(preset) { writer, boltffiValue0 in writer.writeString(boltffiValue0) }
        }
    }
}

